GimCorpus.put(466,0,[[1,8,"האשה אינה יורשת וכו' עד הוא יורש את אשתו. א\"א איני מודה בזה משמעתא בתרייתא דמי שמת ושאר הראיות המראות הפך זה אין להם עמידה עכ\"ל:",1,0],[1,9,"כבר ביארנו בהלכות אישות וכו' עד אין הבעל יורשה. א\"א מה שאמרו במס' גיטין בירושלמי נראה שהוא חולק עליו המגרש את אשתו ולנה עמו בפונדקי בה\"א צריכה ממנו גט שני לאידא מילתא אמר רבי אלעזר לירושה כלומר שהוא יורשה ומה התם בודאי גירשה וספק החזירה יורשה הכא דודאי אשתו היתה וספק גירשה לא כ\"ש:",1,0],[1,13,"אבל אם וכו'. א\"א אינו כן אלא בכלו לו חדשיו דאי לא ידעי הוה ליה איהו ספק והאחין ודאין ואין ספק מוציא מידי ודאי עכ\"ל:",1,0],[3,1,"וכן אם היתה לאביו מלוה וכו' עד יורשין אותה כאחד. א\"א דבר זה למד ממשנת ערכין פ' השג יד עכ\"ל:",1,0],[3,2,"הניח להם פרה מושכרת וכו' עד פי שנים. א\"א זה המחבר פסק כרבי ואין הלכה כרבי עכ\"ל:",1,0],[3,6,"ואפילו וכו' עד וכן כל כיוצא בזה. א\"א יש לנו דרך אחרת בכל זה עכ\"ל:",1,0],[4,6,"מי שהיתה לו שפחה וכו' עד על דבר זה. א\"א בגמרא לא מצאנו בה עיקר דבר זה אבל קצת הגאונים מפולפלים חלקו בין שפחת אחרים לשפחה שלו וגאון אחר חולק עמו מכל מקום לא מצאנו חלוקתם אלא שבעל סתם אבל אם העיד עליו שאמרו משוחררת לא דברו ולענין ירושה יירשנו עכ\"ל:",1,0],[7,3,"מי שטבע במים וכו' עד הרי היורשין נוחלין על פיהם. א\"א ויש מי שאומר שהיא אינה נוטלת כתובתה שאין אני קורא בה כשתנשאי לאחר תטלי מה שכתוב ליכי עכ\"ל:",1,0],[7,4,"שבוי שנשבה וכו'. א\"א תמה אני על דבריו רבותינו אמרו אפילו בלא שמעו בו שמת מורידין קרוב לנכסיו והוא אומר אפילו בששמעו בו שמת אם ירדו לנחלה אין מוציאין מידם (ועוד ביוצא לדעת ששמעו בו שמת מנין לו שמוציאין אותם מידם) עכ\"ל:",1,0],[7,7,"ואין מורידין וכו' עד בורים ונשמים. א\"א אני איני אומר כן כשאמרו שמין להם כאריס לא אמרו אלא כשיבא וימצא שם פירות אבל כל מה שאכל עד שלא בא שלו הוא עכ\"ל:",1,0],[9,2,"אמרו ראו מה שהניח וכו' עד השבח לאמצע. א\"א אין זו הגירסא שלנו ולא של הרב ז\"ל וזה שבוש הוא עכ\"ל:",1,0],[9,4,"מי שירש את אביו וכו' עד שמין לו כאריס. א\"א ואם ידע מה בכך הלא מורידין קרוב לנכסי שבוי קטן אא\"כ יצא לדעת ולא צוה דהיינו רטושין עכ\"ל:",1,0],[9,8,"בד\"א באחים ובאלמנה וכו' עד ואין צריך להביא ראיה. א\"א והיאך גובה בו והא קי\"ל דבעינן כתיבה ומסירה. והנה הוא הולך על דרך פירוש רבו שמפרש אינו צריך ראיה דמצי למימר שטר היה לי ואבד והאי פירושא לא דייק מגופא דהא שמעתא ומשמעתא דסנהדרין במעשה דההיא סבתא דנפק שטרא מתותי ידה עכ\"ל:",1,0],[9,13,"השיא האב את בנו וכו' עד והרי הוא לאמצע. א\"א זה לא ידעתי מהו ולמה לאמצע והלא אינו מחזיר לו אלא חלקו וכשישאו האחרים נשים יחזיר להם חלקם עכ\"ל:",1,0],[10,5,"מי שמת והניח יורשים גדולים וכו' עד שיגדיל. א\"א והוא שחלק להם בחייו שאם לא חלק יניח הכל ביד הגדולים והם ישביחו לאמצע וטוב להם עכ\"ל:",1,0],[11,7,"ואין רשאין וכו' עד ונמצא חוב קיים. א\"א לא זו הדרך אלא שהוא דן לזכות ואם זכה זכו בו היתומים ואם חב לא חב ליתומים שאין להם רשות לאפוטרופסים לחוב ליתומים לא לכתחלה ולא דיעבד עכ\"ל:",1,0],[11,8,"אין האפוטרופין רשאין להוציא וכו' עד שמשחררי'. א\"א יש מי שאומר הלכה כרבי דאמר אף הוא נותן דמי עצמו ויוציא דבהא פליגי דת\"ק סבר אין כסף גומר בה ור' סבר גומר וקי\"ל גומר הלכך הלכתא כר' עכ\"ל:",1,0],[11,9,"האפוטרופין תורמין וכו' עד והרוצה לתקן יתקן. א\"א אין הדעת נוחה הימנו שיהא האפוטרופוס חבר מוכר טבל להכשיל בני אדם בנכסי היתומים. אבל יניח המותר על מזונותיהם לשנה עד שיראה מקום ריוח במכירתם. ואחר ימכור והטעם שאינו שליח אלא לצורך שעה עכ\"ל:",1,0]]);
